<script setup>
import { ref,computed,watch,inject,onBeforeUnmount } from 'vue';
import SubmissionDetails from './SubmissionDetails.vue';
import { useRoute } from 'vue-router';
import { $http } from '@/plugins/axios';
const route=useRoute(),app=inject('collectorApp'),section=computed(()=>route.params.section||'tasks');
const rows=ref([]),error=ref(''),busy=ref(false),status=ref(''),page=ref(1),last=ref(1),detail=ref(null),counts=ref({}),notes=ref({});
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad'}).format(new Date());const from=ref(today),to=ref(today);
const names={requested:'بانتظار الاستلام',collected:'تم استلام العينة',delivered:'تم توصيل العينة',cancelled:'ملغي',pending:'بانتظار مراجعة المختبر',approved:'تم اعتماد الفاتورة',rejected:'مرفوض'};
let version=0;
async function load(){const v=++version;busy.value=true;error.value='';try{if(section.value==='app')return;const {data}=await $http.get('/collector-portal/'+section.value,{params:{status:status.value||undefined,page:page.value,from:from.value,to:to.value}});if(v===version){rows.value=data.data;last.value=data.last_page||1;}}catch(e){if(v===version)error.value=e.response?.data?.message||'تعذر تحميل البيانات؛ حاول مجدداً.';}finally{if(v===version)busy.value=false;}}
async function transition(row){busy.value=true;error.value='';try{await $http.post(`/collector-portal/tasks/${row.id}/status`,{version:row.version,status:row.status==='requested'?'collected':'delivered',sample_count:counts.value[row.id],note:notes.value[row.id]});await load();}catch(e){error.value=e.response?.data?.message||'تعذر تحديث الحالة';}finally{busy.value=false;}}
async function open(row){try{detail.value=(await $http.get('/collector-portal/submissions/'+row.id)).data;}catch(e){error.value=e.response?.data?.message||'تعذر فتح الطلب';}}
async function read(row){await $http.post(`/collector-portal/notifications/${row.id}/read`);await load();app.refreshUnread();}
watch(section,()=>{rows.value=[];status.value='';page.value=1;detail.value=null;load();},{immediate:true});
const timer=setInterval(()=>{if(!document.hidden&&!busy.value&&section.value==='tasks')load();},30000);onBeforeUnmount(()=>{version++;clearInterval(timer);});
</script>
<template><section class="collection-panel"><div class="collection-tools"><h2 class="text-xl font-bold">{{{tasks:'طلبات سحب العينات',submissions:'فواتيري المرسلة',statistics:'إحصائياتي',notifications:'الإشعارات',app:'التطبيق والإشعارات'}[section]}}</h2><button :disabled="busy" @click="load">تحديث</button></div><p v-if="error" role="alert">{{error}}</p><div v-if="['tasks','submissions'].includes(section)" class="collection-tools"><label>حالة الطلب<select v-model="status" @change="page=1;load()"><option value="">جميع الحالات</option><option v-for="key in (section==='tasks'?['requested','collected','delivered','cancelled']:['pending','approved','rejected'])" :key="key" :value="key">{{names[key]}}</option></select></label></div><div v-if="section==='statistics'" class="collection-tools"><label>من<input type="date" v-model="from"></label><label>إلى<input type="date" v-model="to"></label><button @click="load">عرض</button></div>
<template v-if="section==='tasks'"><article v-for="row in rows" :key="row.id" class="collection-card"><small>طلب #{{row.id}} · فاتورة #{{row.invoice_id}}</small><h2>{{row.details.patient?.name}}</h2><p>{{names[row.status]}} · {{row.details.patient?.age}} {{row.details.patient?.age_unit}}</p><div class="my-3"><strong>{{row.details.source?.name}}</strong><p>{{row.details.source?.address}}</p><a v-if="row.details.source?.phone" dir="ltr" :href="'tel:'+row.details.source.phone">{{row.details.source.phone}}</a></div><ul><li v-for="(item,i) in row.details.items" :key="i" class="my-2"><strong>{{item.name}}</strong><span v-if="item.sample"> · {{item.sample}}</span><p v-for="(child,j) in item.children" :key="j">{{j+1}}. {{child.name}} <small>{{child.sample}}</small></p></li></ul><p v-if="row.sample_count">عدد العينات: {{row.sample_count}}</p><div v-if="['requested','collected'].includes(row.status)" class="collection-tools"><label v-if="row.status==='requested'">عدد العينات المستلمة<input v-model.number="counts[row.id]" type="number" min="1" max="10000"></label><label>ملاحظة<input v-model="notes[row.id]" maxlength="2000"></label><button :disabled="busy||(row.status==='requested'&&!counts[row.id])" @click="transition(row)">{{row.status==='requested'?'تأكيد استلام العينة':'تأكيد توصيل العينة'}}</button></div></article></template>
<template v-if="section==='submissions'"><article v-for="row in rows" :key="row.id" class="collection-card"><h2>{{row.patient_name}}</h2><p>{{names[row.status]}} · {{row.total}} د.ع</p><p>{{row.review_note}}</p><button @click="open(row)">تفاصيل الطلب #{{row.id}}</button></article><div v-if="detail" class="collection-card"><button @click="detail=null">إغلاق التفاصيل</button><SubmissionDetails :detail="detail"/></div></template>
<template v-if="section==='statistics'"><p>تُحسب العينات حسب وقت الاستلام والتوصيل بتوقيت بغداد. عدد الطلبات مستقل عن عدد العينات.</p><div v-for="row in rows" :key="row.id" class="collection-stats"><div v-for="[key,label] in [['collected_samples','عينات مستلمة'],['delivered_samples','عينات موصلة'],['collected_requests','طلبات مستلمة'],['delivered_requests','طلبات موصلة'],['pending','طلبات حالية غير مكتملة']]" :key="key" class="collection-card"><strong>{{row[key]}}</strong>{{label}}</div></div></template>
<template v-if="section==='notifications'"><article v-for="row in rows" :key="row.id" class="collection-card"><h2>{{row.title}}</h2><p>{{row.body}}</p><button v-if="!row.read_at" @click="read(row)">تمت القراءة</button><RouterLink :to="row.task_id?'/collector-portal/tasks':'/collector-portal/submissions'"> فتح القائمة</RouterLink></article></template>
<div v-if="section==='app'" class="collection-card"><h2>تطبيق ساحب العينات</h2><p>أضف البوابة إلى الشاشة الرئيسية للوصول السريع.</p><button v-if="app.installAvailable" @click="app.install">تثبيت التطبيق</button><p v-else>من قائمة المتصفح اختر الإضافة إلى الشاشة الرئيسية. على آيفون استخدم قائمة المشاركة في Safari.</p><div class="collection-tools"><button v-if="!app.subscribed" :disabled="!app.ready||app.busy" @click="app.enable">تفعيل الإشعارات</button><button v-else :disabled="app.busy" @click="app.disable">إيقاف إشعارات هذا الجهاز</button><button @click="app.prepare">إعادة فحص الإعدادات</button></div><p v-if="app.config&&!app.config.enabled">تحتاج خدمة الإشعارات إلى تفعيل من مدير النظام.</p><p role="alert">{{app.error}}</p><p>{{app.message}}</p></div>
<p v-if="!busy&&!rows.length&&section!=='app'" class="collection-card">لا توجد بيانات ضمن الاختيارات الحالية.</p><div v-if="last>1" class="collection-tools"><button :disabled="page===1||busy" @click="page--;load()">السابق</button><span>{{page}} / {{last}}</span><button :disabled="page===last||busy" @click="page++;load()">التالي</button></div></section></template>
